    # Nueve de los dieciocho temas. Cinco van PARAMÉTRICAS porque la auditoría las
    # marca con ⚙: un banco fijo de 20 ítems se memoriza en dos partidas
    # ([[ct3d-memorizacion-bancos]]), y estos temas son justo los que el chico
